void USocialTradeComponent::ProcessTransaction(FString ItemName, int32 Quantity, float Price)
{
	if (!bTradeActive)
	{
		UE_LOG(LogTemp, Warning, TEXT("[SocialTrade] Cannot process transaction: trade not active"));
		return;
	}

	if (Quantity <= 0)
	{
		UE_LOG(LogTemp, Warning, TEXT("[SocialTrade] Invalid quantity: %d"), Quantity);
		return;
	}

	float FinalPrice = Price;
	if (Quantity > 10)
	{
		FinalPrice = Price * TradeDiscount;  // Volume discount for bulk purchases
		UE_LOG(LogTemp, Display, TEXT("[SocialTrade] Applied volume discount (10+ units): %.2f -> %.2f"),
			Price, FinalPrice);
	}
	else
	{
		FinalPrice = Price * TradeMarkup;    // Standard markup for small purchases
		UE_LOG(LogTemp, Display, TEXT("[SocialTrade] Applied standard markup: %.2f -> %.2f"),
			Price, FinalPrice);
	}

	UE_LOG(LogTemp, Display, TEXT("[SocialTrade] Transaction processed - Item: %s, Qty: %d, Price: %.2f (final)"),
		*ItemName, Quantity, FinalPrice);

	// In a full implementation:
	// - Deduct FinalPrice from player credits
	// - Add ItemName x Quantity to player inventory
	// - Add item to NPC's "sold" history for reputation
	// - Update NPC's standing with the player faction

	bTradeActive = false;
}
